wire [3:0] mux_out;
assign mux_out = (write_en) ? in : shifted_in;

assign out1 = in;
assign out2 = mux_out;

wire [3:0] and_out;
assign and_out = read_data & mux_out;

assign and_output = and_out;

endmodule

