module top_module (
	input clk,
	input areset,
	input x,
	input y,
	output gt);parameter LESS=0, GREATER=1, EQUAL=2;
	reg [1:0] state;
	always @(posedge clk or posedge areset) begin
		if (areset)
			state <= EQUAL;
		else begin
			case (state)
				LESS: state <= LESS;
				GREATER: state <= GREATER;
				EQUAL: begin
					if (x > y)
						state <= GREATER;
					else if (x < y)
						state <= LESS;
					else
						state <= EQUAL;
				end
			endcase
		end
	end

	assign gt = (state == GREATER);

endmodule

