module top_module(
    input clk,
    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input [3:0] data,
    output reg [3:0] q,
    output reg [3:0] final_output
);reg [3:0] counter;
    reg [3:0] shift_reg;
    wire [3:0] shift_reg_out;

    // Counter
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            counter <= 4'b0000;
        end else if (ena) begin
            counter <= counter + 1;
        end
    end

    // Shift Register
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            shift_reg <= 4'b0000;
        end else if (load) begin
            shift_reg <= data;
        end else if (ena) begin
            shift_reg <= {1'b0, shift_reg[3:1]};
        end
    end

    // Functional Module
    always @(*) begin
        if (counter > shift_reg) begin
            final_output = counter;
        end else begin
            final_output = shift_reg;
        end
    end

    // Multiplexers
    assign q = load ? data : shift_reg_out;
    assign shift_reg_out = load ? data : shift_reg;

endmodule

