module top_module(
    input clk,
    input reset_shift, // Active high synchronous reset for shift register
    input reset_flipflop, // Active low asynchronous reset for D flip-flop
    input [7:0] in,
    output [7:0] anyedge,
    output reg [3:0] num_edges // 4-bit binary number output from functional module
);reg [7:0] shift_reg;
reg [7:0] delayed_reg;
reg [7:0] edge_detect;
reg [7:0] edge_detect_delayed;
reg rising_edge_detected;

always @(posedge clk) begin
    if (reset_shift) begin
        shift_reg <= 8'b0;
        delayed_reg <= 8'b0;
        edge_detect <= 8'b0;
        edge_detect_delayed <= 8'b0;
        rising_edge_detected <= 1'b0;
    end else begin
        shift_reg <= {in, shift_reg[7:1]};
        delayed_reg <= shift_reg;
        edge_detect <= shift_reg ^ delayed_reg;
        edge_detect_delayed <= {edge_detect[6:0], 1'b0};
        rising_edge_detected <= edge_detect_delayed[7];
    end
end

reg [7:0] flipflop_input;
reg [7:0] flipflop_output;

always @(posedge clk or negedge reset_flipflop) begin
    if (!reset_flipflop) begin
        flipflop_input <= 8'b0;
        flipflop_output <= 8'b0;
    end else begin
        flipflop_input <= {rising_edge_detected, flipflop_input[7:1]};
        flipflop_output <= flipflop_input;
    end
end

assign anyedge = flipflop_output;

reg [3:0] edge_count;

always @(posedge clk) begin
    if (reset_shift) begin
        edge_count <= 4'b0;
    end else if (rising_edge_detected) begin
        edge_count <= edge_count + 1;
    end
end

always @(posedge clk) begin
    if (reset_shift) begin
        num_edges <= 4'b0;
    end else begin
        num_edges <= edge_count;
    end
end

endmodule

