module top_module (
        input clk,
        input areset,
        input power_on,
        input power_off,
        input temp_reached,
        output reg heater);parameter Off=2'b00, Heating=2'b01, Standby=2'b10;
	reg [1:0] state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= Off;
		else begin
			case (state)
				Off: state <= power_on ? Heating : Off;
				Heating: state <= temp_reached ? Standby : Heating;
				Standby: state <= power_off ? Off : Standby;
			endcase
		end
	end

	assign heater = (state == Heating);

endmodule

