module top_module (
  input in1,
  input in2,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter M=2'b00, N=2'b01, O=2'b10;

    always_comb begin
		case (state)
			M: next_state = (in1 == 0 && in2 == 1) ? N : O;
			N: next_state = (in1 == 0 && in2 == 1) ? O : M;
			O: next_state = (in1 == 0 && in2 == 1) ? M : N;
		endcase
    end

    always_comb begin
		case (state)
			M: out = 0;
			N: out = 1;
			O: out = 0;
		endcase
    end

endmodule

