description:
Design a 4-bit binary counter that increments on each rising edge of the clock signal. The counter rolls over to zero after reaching a count of 15 (binary 1111). The output is registered, ensuring stable values throughout the counting process, with intermediate registers used to store values across the clock cycles before updating the final output.
module top_module(
    input clk,
    output reg [3:0] Q
);

code:
module top_module(
    input clk,
    output reg [3:0] Q
);reg [3:0] Q_reg1, Q_reg2, Q_reg3;

always @(posedge clk) begin
    Q_reg1 <= Q;
end

always @(posedge clk) begin
    Q_reg2 <= Q_reg1;
end

always @(posedge clk) begin
    Q_reg3 <= Q_reg2;
end

always @(posedge clk) begin
    if (Q_reg3 == 4'b1111) begin
        Q <= 4'b0000;
    end else begin
        Q <= Q_reg3 + 1;
    end
end

endmodule

