description:
Design a 4-bit pipelined Johnson counter that operates on a clock signal and supports asynchronous reset. The counter shifts a 64-bit register on each clock cycle, using a specific feedback mechanism to generate the next state. The most significant 4 bits of this shift register are outputted as the counter value, while the state is updated based on a linear feedback shift register (LFSR) technique. When reset is active, both the shift register and the counter output are initialized to zero.
module top_module(
  input                clk,
  input                rst_n,
  output reg  [3:0]    Q
);

code:
module top_module(
  input                clk,
  input                rst_n,
  output reg  [3:0]    Q
);reg [63:0] shift_reg;
  reg [3:0]  next_state;

  always @(posedge clk) begin
    if (!rst_n) begin
      shift_reg <= 64'b0;
      Q <= 4'b0;
      next_state <= 4'b0001;
    end
    else begin
      shift_reg <= {shift_reg[62:0], shift_reg[63] ^ shift_reg[60]};
      Q <= shift_reg[63:60];
      next_state <= {next_state[2:0], next_state[3] ^ next_state[0]};
    end
  end

  always @(posedge clk) begin
    if (!rst_n) begin
      Q <= 4'b0;
    end
    else begin
      Q <= next_state;
    end
  end

endmodule

